import com.sun.net.httpserver.HttpServer;
import com.sun.net.httpserver.HttpExchange;

import java.net.InetSocketAddress;
import java.io.IOException;
import java.io.OutputStream;

public class Main {

    public static void main(String[] args) throws IOException {

        HttpServer server = HttpServer.create(new InetSocketAddress(38451), 0);

        server.createContext("/hello", exchange -> {
            try {
                String origin = exchange.getRequestHeaders().getFirst("Origin");

                // Allow only your dev server
                if ("http://localhost:3000".equals(origin)) {
                    exchange.getResponseHeaders().add("Access-Control-Allow-Origin", origin);
                }

                exchange.getResponseHeaders().add("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
                exchange.getResponseHeaders().add("Access-Control-Allow-Headers", "Content-Type");
                exchange.getResponseHeaders().add("Access-Control-Allow-Credentials", "true");

                // Handle preflight requests
                if ("OPTIONS".equalsIgnoreCase(exchange.getRequestMethod())) {
                    exchange.sendResponseHeaders(204, -1);
                    return;
                }
                Test t = new Test();
                String response = "Hello from Java backend v8! " + t.test1() + " | " + t.test2();
                exchange.sendResponseHeaders(200, response.length());

                OutputStream os = exchange.getResponseBody();
                os.write(response.getBytes());
                os.close();

            } catch (IOException e) {
                e.printStackTrace();
            }
        });


        server.start();
        System.out.println("Java backend started");
    }
}
